// T041 接口基础与鸭子类型。
//
// Go 的接口是“方法集合”：任何类型只要实现了接口要求的全部方法，就自动满足
// 该接口——无需显式声明 implements。这叫结构化类型 / 鸭子类型。
// 本示例定义 Shape 接口，让 Circle 与 Rectangle 各自实现，再统一调用。
package main

import (
	"fmt"
	"math"
)

// Shape 是接口：任何能给出面积与周长的类型都算 Shape。
type Shape interface {
	Area() float64
	Perimeter() float64
}

// Circle 实现 Shape。
type Circle struct{ R float64 }

func (c Circle) Area() float64      { return math.Pi * c.R * c.R }
func (c Circle) Perimeter() float64 { return 2 * math.Pi * c.R }

// Rectangle 也实现 Shape。
type Rectangle struct{ W, H float64 }

func (r Rectangle) Area() float64      { return r.W * r.H }
func (r Rectangle) Perimeter() float64 { return 2 * (r.W + r.H) }

// describe 只依赖 Shape 接口，不关心具体类型。
func describe(s Shape) string {
	return fmt.Sprintf("area=%.2f perimeter=%.2f", s.Area(), s.Perimeter())
}

func main() {
	// 隐式满足：Circle 与 Rectangle 都没有写 "implements Shape"。
	shapes := []Shape{Circle{R: 1}, Rectangle{W: 2, H: 3}}
	for i, s := range shapes {
		fmt.Printf("shape %d: %s\n", i, describe(s))
	}

	// 接口值可以为 nil；对 nil 接口调用方法会 panic，注意判空。
	var s Shape
	fmt.Println("nil interface is nil:", s == nil)
}

// T042 接口的动态类型与类型断言。
//
// 接口值内部保存“动态类型 + 动态值”。用类型断言 x.(T) 取出具体类型：
// 单返回值形式在失败时 panic，逗号-ok 形式安全返回零值与 false。
// 本示例演示两种断言与安全降级。
package main

import "fmt"

// Stringer 是一个简单接口。
type Stringer interface {
	String() string
}

// Name 实现了 Stringer。
type Name string

func (n Name) String() string { return string(n) }

// Number 也实现了 Stringer，便于在同一接口值上演示断言成功/失败。
type Number int

func (n Number) String() string { return fmt.Sprintf("#%d", int(n)) }

func main() {
	var s Stringer = Name("gopher")

	// 安全的逗号-ok 断言：成功时 ok 为 true。
	name, ok := s.(Name)
	fmt.Println("assert Name ok:", ok, "value:", name)

	// 失败断言：动态类型是 Name，断言为 Number 不成立，返回零值与 false。
	_, ok = s.(Number)
	fmt.Println("assert Number while type is Name:", ok)

	// 单返回值形式在失败时 panic；示例用 recover 演示其代价。
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Println("single-value assert panicked:", r != nil)
			}
		}()
		_ = s.(Number) // 会 panic
	}()

	// 动态类型改赋为 Number；此时断言成功并取到值。
	s = Number(7)
	n, ok := s.(Number)
	fmt.Println("after reassign assert Number ok:", ok, "value:", int(n))

	// 对 any 的接口值断言为 string。
	var anyv any = "text"
	if str, ok := anyv.(string); ok {
		fmt.Println("any->string ok:", str)
	}
}

// T043 空接口、any 与类型 switch。
//
// any（即 interface{}）能装任何值。用类型 switch 可以在一个 switch 里
// 按动态类型分发处理，是处理异构集合的常用手段。
package main

import "fmt"

// classify 用类型 switch 对任意值分类，返回可读描述。
func classify(v any) string {
	switch x := v.(type) {
	case nil:
		return "nil"
	case int:
		return fmt.Sprintf("int=%d", x)
	case float64:
		return fmt.Sprintf("float64=%.1f", x)
	case string:
		return fmt.Sprintf("string=%q len=%d", x, len(x))
	case bool:
		return fmt.Sprintf("bool=%t", x)
	case []int:
		return fmt.Sprintf("[]int len=%d", len(x))
	default:
		return fmt.Sprintf("other(%T)", x)
	}
}

func main() {
	// 异构集合：混合类型放进同一个 []any。
	values := []any{nil, 1, 2.5, "go", true, []int{1, 2, 3}, struct{ X int }{X: 9}}

	counts := map[string]int{}
	for _, v := range values {
		desc := classify(v)
		fmt.Println(desc)
		// 按类型名统计，演示对类型 switch 结果的再处理。
		switch v.(type) {
		case int:
			counts["int"]++
		case string:
			counts["string"]++
		default:
			counts["other"]++
		}
	}
	fmt.Println("int count:", counts["int"], "string count:", counts["string"], "other:", counts["other"])
}

// T044 接口组合与最小接口原则。
//
// Go 鼓励“小而专”的接口：Reader、Writer、Closer 各管一件事，再按需组合。
// 接口可以嵌入接口形成组合接口，如 ReadWriteCloser = Reader+Writer+Closer。
// 本示例用合成接口统一读写设备，并演示最小接口的好处。
package main

import (
	"fmt"
	"strings"
)

// Reader / Writer / Closer 是最小的单方法接口。
type Reader interface{ Read() string }
type Writer interface{ Write(s string) }
type Closer interface{ Close() error }

// ReadWriteCloser 组合三个最小接口。
type ReadWriteCloser interface {
	Reader
	Writer
	Closer
}

// MemDevice 实现了全部三个方法，因此满足组合接口。
type MemDevice struct {
	data   string
	closed bool
}

func (d *MemDevice) Read() string { return d.data }
func (d *MemDevice) Write(s string) {
	d.data += s
}
func (d *MemDevice) Close() error {
	d.closed = true
	return nil
}

// useReader 只需要最小的 Reader 接口，任何能 Read 的类型都能传入。
func useReader(r Reader) string { return r.Read() }

func main() {
	var dev ReadWriteCloser = &MemDevice{data: "start"}

	dev.Write("-more")
	fmt.Println("read:", useReader(dev)) // 组合接口可赋给最小接口

	if err := dev.Close(); err != nil {
		panic(err)
	}
	fmt.Println("closed:", dev.(*MemDevice).closed)

	// 只实现 Read 的轻量类型也能满足 Reader，便于替换与测试。
	lit := strings.NewReader("literal")
	_ = lit
	fmt.Println("minimal interface reuse: a one-method type satisfies Reader")
}

// T045 标准接口：Stringer 与 error。
//
// fmt.Stringer 的 String() 方法决定 fmt 打印该值时的文本；
// error 接口的 Error() 同理决定错误文本。实现它们即可定制输出。
package main

import (
	"errors"
	"fmt"
)

// Color 实现 Stringer。
type Color int

const (
	Red Color = iota
	Green
	Blue
)

func (c Color) String() string {
	switch c {
	case Red:
		return "RED"
	case Green:
		return "GREEN"
	case Blue:
		return "BLUE"
	default:
		return fmt.Sprintf("Color(%d)", int(c))
	}
}

// ValidationError 实现 error。
type ValidationError struct {
	Field string
	Msg   string
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("validation failed on %s: %s", e.Field, e.Msg)
}

func main() {
	// 有 String() 后，%v/%s 打印的是名字而非数字。
	fmt.Println("color:", Red)
	fmt.Printf("color with %%v: %v, %%d: %d\n", Green, Green)

	// 越界值走回退分支。
	fmt.Println("unknown:", Color(99))

	// error 值：Error() 决定 %v 输出。
	var err error = &ValidationError{Field: "age", Msg: "must be positive"}
	fmt.Println("error:", err)

	// errors.Is 对指针错误按身份匹配（此处与本身比较）。
	fmt.Println("same error:", errors.Is(err, err))
}

// T046 排序与比较：sort.Interface 实现。
//
// sort.Interface 要求三个方法：Len、Less、Swap。实现它即可用 sort.Sort
// 排序任意集合。Less 决定顺序，Swap 决定交换方式。
package main

import (
	"fmt"
	"sort"
)

// Person 是要排序的元素。
type Person struct {
	Name string
	Age  int
}

// ByAge 是 []Person 的排序视图：先按年龄，年龄相同按名字。
type ByAge []Person

func (p ByAge) Len() int      { return len(p) }
func (p ByAge) Swap(i, j int) { p[i], p[j] = p[j], p[i] }
func (p ByAge) Less(i, j int) bool {
	if p[i].Age != p[j].Age {
		return p[i].Age < p[j].Age
	}
	return p[i].Name < p[j].Name
}

func main() {
	people := []Person{
		{"carol", 30},
		{"alice", 25},
		{"bob", 30},
		{"dave", 20},
	}

	// sort.Sort 会读取 Len/Less/Swap 完成排序。
	sort.Sort(ByAge(people))
	for _, p := range people {
		fmt.Printf("%-6s %d\n", p.Name, p.Age)
	}

	// 用 sort.Sort(sort.Reverse(...)) 得到逆序。
	sort.Sort(sort.Reverse(ByAge(people)))
	fmt.Println("reversed first:", people[0].Name)
}

// T047 组合优于继承：策略与装饰模式。
//
// Go 没有继承，用“接口 + 组合”实现行为的可替换与增强：
// 策略模式把可变的算法抽成接口，装饰模式用组合在原有行为上叠加。
package main

import (
	"fmt"
	"strings"
)

// Pricing 是价格计算策略。
type Pricing interface {
	Price(base int) int
}

// NormalPrice 原价。
type NormalPrice struct{}

func (NormalPrice) Price(base int) int { return base }

// DiscountPrice 打八折。
type DiscountPrice struct{}

func (DiscountPrice) Price(base int) int { return base * 8 / 10 }

// Order 组合一个 Pricing 策略（而非继承一个具体类）。
type Order struct {
	base     int
	strategy Pricing
}

// Total 委托给当前策略，切换策略即改变行为。
func (o *Order) Total() int { return o.strategy.Price(o.base) }

// Job 是被装饰的核心行为。
type Job interface {
	Run() string
}

// SimpleJob 基础实现。
type SimpleJob struct{ name string }

func (j SimpleJob) Run() string { return "run " + j.name }

// LogJob 是装饰器：在原有 Job 前后叠加日志（组合，而非改写 SimpleJob）。
type LogJob struct {
	inner Job
	lines *[]string
}

func (l LogJob) Run() string {
	*l.lines = append(*l.lines, "before "+l.inner.Run())
	out := l.inner.Run()
	*l.lines = append(*l.lines, "after "+l.inner.Run())
	return out
}

func main() {
	o := &Order{base: 100, strategy: NormalPrice{}}
	fmt.Println("normal total:", o.Total())

	o.strategy = DiscountPrice{} // 运行期切换策略
	fmt.Println("discount total:", o.Total())

	var lines []string
	var job Job = SimpleJob{name: "build"}
	job = LogJob{inner: job, lines: &lines} // 装饰
	fmt.Println("decorated run:", job.Run())
	fmt.Println("log lines:")
	for _, l := range lines {
		fmt.Println(" ", strings.TrimSpace(l))
	}
}

// T048 接口的 nil 陷阱与类型比较。
//
// 一个常见陷阱：接口值为 nil 与“接口里装了一个 nil 的具体指针”不是一回事。
// 本示例演示 typed-nil 陷阱：接口非 nil，但内部动态值为 nil，调用方法会 panic。
package main

import "fmt"

// Greeter 是接口。
type Greeter interface {
	Greet() string
}

// Person 实现 Greeter。
type Person struct{ Name string }

func (p *Person) Greet() string { return "hi " + p.Name }

func main() {
	// 情形一：真正的 nil 接口。
	var g Greeter
	fmt.Println("nil interface == nil:", g == nil)

	// 情形二：typed-nil 陷阱。把一个 nil 的 *Person 放进接口。
	var p *Person // p 是 nil
	g = p         // 接口非 nil，但动态类型是 *Person、动态值是 nil
	fmt.Println("typed-nil interface == nil:", g == nil) // 输出 false！

	// 调用会 panic，因为方法在 nil 接收者上解引用字段。
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Println("calling method on typed-nil panicked:", r != nil)
			}
		}()
		_ = g.Greet()
	}()

	// 正确做法：用类型断言判断内部是否为 nil 指针。
	if pp, ok := g.(*Person); ok && pp == nil {
		fmt.Println("detected typed-nil via assertion")
	}

	// 有实际值时正常。
	g = &Person{Name: "gopher"}
	fmt.Println("real value:", g.Greet())
}

// T049 error 接口与错误即值。
//
// Go 把错误当作普通值返回：函数返回 (T, error)，调用方必须显式检查。
// error 是一个接口：任何有 Error() string 的类型都能当错误。
package main

import "fmt"

// divide 在两个数相除时检查除零并返回错误。
func divide(a, b int) (int, error) {
	if b == 0 {
		return 0, fmt.Errorf("divide by zero")
	}
	return a / b, nil
}

func main() {
	// 成功：err 为 nil。
	q, err := divide(10, 2)
	fmt.Println("10/2 =", q, "err:", err)

	// 失败：检查 err 并降级处理，而不是忽略。
	q, err = divide(1, 0)
	if err != nil {
		fmt.Println("error:", err)
		fmt.Println("result unusable, defaulting to 0")
		q = 0
	}
	fmt.Println("value after error:", q)

	// 错误是值：可以存入变量、比较、传递。
	var lastErr error
	if _, e := divide(3, 0); e != nil {
		lastErr = e
	}
	fmt.Println("stored error text:", lastErr.Error())
}

// T050 errors.New、fmt.Errorf 与哨兵错误。
//
// 哨兵错误（sentinel error）是包级导出的错误变量，调用方用 errors.Is
// 判断错误身份，而不比较错误字符串——字符串比较脆弱，包装后即失效。
package main

import (
	"errors"
	"fmt"
)

// ErrNotFound 是一个哨兵错误。
var ErrNotFound = errors.New("not found")

// lookup 在缺少键时返回哨兵错误（可能被外层包装）。
func lookup(m map[string]int, key string) (int, error) {
	v, ok := m[key]
	if !ok {
		return 0, ErrNotFound
	}
	return v, nil
}

// withContext 在外层用 %w 包装，保留可被 errors.Is 识别的原始错误。
func withContext(err error, key string) error {
	return fmt.Errorf("lookup %q: %w", key, err)
}

func main() {
	m := map[string]int{"a": 1}

	v, err := lookup(m, "a")
	fmt.Println("found a:", v, "err:", err)

	_, err = lookup(m, "missing")
	fmt.Println("errors.Is ErrNotFound:", errors.Is(err, ErrNotFound))

	// 包装后仍然可以用 errors.Is 命中哨兵。
	wrapped := withContext(ErrNotFound, "missing")
	fmt.Println("wrapped text:", wrapped)
	fmt.Println("wrapped Is ErrNotFound:", errors.Is(wrapped, ErrNotFound))

	// 直接比较字符串是脆弱的，示例说明不要这样做。
	fmt.Println("string compare is fragile:", errors.Is(err, ErrNotFound))
}

// T051 错误包装与 %w 的解包链。
//
// %w 在 fmt.Errorf 中表示“包装”错误，形成可解包的链：
// errors.Unwrap 逐层取出内层错误，errors.Is/As 则会遍历整条链。
package main

import (
	"errors"
	"fmt"
)

var errBase = errors.New("base failure")

// level3 最内层返回基础错误。
func level3() error { return errBase }

// level2 包装一层。
func level2() error { return fmt.Errorf("level2: %w", level3()) }

// level1 再包装一层。
func level1() error { return fmt.Errorf("level1: %w", level2()) }

func main() {
	err := level1()

	// 完整文本保留每一层的上下文。
	fmt.Println("full:", err)

	// 逐层解包，打印链上每一层。
	fmt.Println("unwrap chain:")
	for e := err; e != nil; e = errors.Unwrap(e) {
		fmt.Println(" ", e)
	}

	// errors.Is 会遍历整条链命中基础错误。
	fmt.Println("Is(errBase):", errors.Is(err, errBase))

	// 使用 %v（而非 %w）只做文本拼接，不构成可解包链。
	noChain := fmt.Errorf("context: %v", errBase)
	directive := "%v"
	fmt.Println("with "+directive+" Is(errBase):", errors.Is(noChain, errBase))
}

// T052 errors.Is 与 errors.As 的适用差异。
//
// errors.Is 用于“值/身份”匹配（哨兵错误），遍历解包链比较；
// errors.As 用于“类型”匹配，把链上某个具体类型的错误取出到目标变量，读取其字段。
package main

import (
	"errors"
	"fmt"
)

// PathError 是带字段的自定义错误类型。
type PathError struct {
	Path string
	Op   string
}

func (e *PathError) Error() string { return e.Op + " " + e.Path + ": failed" }

var ErrPermission = errors.New("permission denied")

// open 在路径含 "secret" 时返回带类型的错误，否则返回哨兵错误。
func open(path string) error {
	if len(path) >= 6 && path[:6] == "secret" {
		return &PathError{Path: path, Op: "open"}
	}
	return fmt.Errorf("open %s: %w", path, ErrPermission)
}

func main() {
	// errors.Is：判断是否属于某个哨兵错误（值匹配）。
	err := open("data.txt")
	fmt.Println("Is ErrPermission:", errors.Is(err, ErrPermission))

	// errors.As：把具体类型取出，读取其字段（类型匹配）。
	err = open("secret.cfg")
	var pe *PathError
	if errors.As(err, &pe) {
		fmt.Println("As PathError -> path:", pe.Path, "op:", pe.Op)
	}

	// As 对内层包装同样生效。
	inner := fmt.Errorf("wrapped: %w", &PathError{Path: "a", Op: "read"})
	var pe2 *PathError
	fmt.Println("As on wrapped:", errors.As(inner, &pe2), pe2.Op)
}

// T053 自定义错误类型与行为方法。
//
// 自定义错误类型可携带结构化信息（字段）并实现额外方法，比字符串错误更有用。
// 实现 Unwrap 还能融入 errors.Is/As 链。
package main

import (
	"errors"
	"fmt"
)

// QueryError 携带 SQL 与原因，并实现 Unwrap 暴露底层错误。
type QueryError struct {
	SQL   string
	Cause error
}

func (e *QueryError) Error() string {
	return fmt.Sprintf("query %q failed: %v", e.SQL, e.Cause)
}

func (e *QueryError) Unwrap() error { return e.Cause }

var ErrTimeout = errors.New("timeout")

// run 返回包装了哨兵错误的 QueryError。
func run(sql string) error {
	return &QueryError{SQL: sql, Cause: ErrTimeout}
}

func main() {
	err := run("SELECT 1")

	// Error() 决定可读文本。
	fmt.Println("text:", err)

	// Unwrap 让 errors.Is 能命中底层哨兵。
	fmt.Println("Is ErrTimeout:", errors.Is(err, ErrTimeout))

	// errors.As 取出带字段的类型并读取元数据。
	var qe *QueryError
	if errors.As(err, &qe) {
		fmt.Println("SQL field:", qe.SQL)
		fmt.Println("Cause field:", qe.Cause)
	}

	// errors.Unwrap 直接取出内层。
	fmt.Println("Unwrap == ErrTimeout:", errors.Unwrap(err) == ErrTimeout)
}

// T054 panic 与 recover：边界与代价。
//
// panic 表示不可继续的程序错误；recover 只能在 defer 中调用，用于兜底。
// 惯例：库函数用 error，不使用 panic；recover 一般只用在进程/请求边界。
package main

import "fmt"

// safeDivide 用 recover 把除零 panic 转成 error（边界兜底）。
func safeDivide(a, b int) (result int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("recovered: %v", r)
		}
	}()
	return a / b, nil // b==0 时 panics，被上面 recover 捕获
}

// mustPositive panics 表示违反前提（不可恢复）。
func mustPositive(n int) int {
	if n <= 0 {
		panic("n must be positive")
	}
	return n
}

func main() {
	// 正常路径。
	r, err := safeDivide(10, 2)
	fmt.Println("10/2:", r, "err:", err)

	// 除零被 recover 转成 error，程序继续运行。
	r, err = safeDivide(1, 0)
	fmt.Println("1/0 ->", r, "err:", err)

	// 直接 panic 且不 recover 会终止程序；示例用 recover 演示其可被捕获。
	func() {
		defer func() {
			fmt.Println("caught panic:", recover())
		}()
		mustPositive(0)
	}()

	fmt.Println("program continues after recovered panic")
}

// T055 defer 在资源清理与错误聚合中的应用。
//
// defer 在函数返回时执行（LIFO），常用于释放资源。
// 通过命名返回值，defer 可以合并多个清理步骤的错误——避免“只返回最后一个错误”丢因。
package main

import (
	"errors"
	"fmt"
)

// closer 模拟可关闭资源。
type closer struct {
	name string
	err  error
}

func (c *closer) Close() error {
	if c.err != nil {
		return fmt.Errorf("close %s: %w", c.name, c.err)
	}
	return nil
}

// process 打开两个资源，用 defer 关闭并聚合关闭错误。
func process(a, b *closer) (err error) {
	// defer 在 return 之后执行，可修改命名返回值 err。
	defer func() {
		if cerr := a.Close(); cerr != nil {
			err = errors.Join(err, cerr) // 合并，而非覆盖
		}
		if cerr := b.Close(); cerr != nil {
			err = errors.Join(err, cerr)
		}
	}()
	return nil
}

func main() {
	// 两个都正常关闭。
	if err := process(&closer{name: "a"}, &closer{name: "b"}); err != nil {
		fmt.Println("unexpected:", err)
	} else {
		fmt.Println("both closed cleanly")
	}

	// a 关闭失败：错误被保留。
	errA := errors.New("disk io")
	err := process(&closer{name: "a", err: errA}, &closer{name: "b"})
	fmt.Println("close error:", err)
	fmt.Println("preserved cause:", errors.Is(err, errA))

	// defer 的 LIFO 顺序演示。
	func() {
		for i := 1; i <= 3; i++ {
			defer fmt.Println("deferred", i)
		}
		fmt.Println("body done")
	}()
}

// T056 错误处理模式：立即返回与上下文补充。
//
// 惯例：错误产生处立即 return，调用链每一层用 %w 补充上下文（哪个操作、哪个键），
// 到边界处统一打印一次。这样既不丢因，又能给出可定位的路径。
package main

import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("not found")

// 最底层：只返回原始错误。
func readConfig(m map[string]string, key string) (string, error) {
	v, ok := m[key]
	if !ok {
		return "", ErrNotFound
	}
	return v, nil
}

// 中层：补充“读取哪个配置”的上下文。
func loadConfig(m map[string]string) (string, error) {
	v, err := readConfig(m, "db.dsn")
	if err != nil {
		return "", fmt.Errorf("loadConfig: %w", err)
	}
	return v, nil
}

// 上层：再补充“启动阶段”上下文。
func start(m map[string]string) error {
	if _, err := loadConfig(m); err != nil {
		return fmt.Errorf("start: %w", err)
	}
	return nil
}

func main() {
	// 空配置：错误链包含每一层上下文。
	err := start(map[string]string{})
	fmt.Println("error chain:", err)
	fmt.Println("still Is ErrNotFound:", errors.Is(err, ErrNotFound))

	// 逐层打印，展示上下文补充效果。
	for e := err; e != nil; e = errors.Unwrap(e) {
		fmt.Println("  -", e)
	}

	// 有配置时成功。
	if err := start(map[string]string{"db.dsn": "postgres://x"}); err != nil {
		fmt.Println("unexpected:", err)
	} else {
		fmt.Println("started ok")
	}
}

// T057 错误与日志打印边界。
//
// 反模式：每一层都 log 一次，同一个错误被打印多遍，噪音大且难追踪。
// 惯例：中间层只 return（可包装），到“边界”（main、HTTP handler、job runner）
// 才记录一次日志或向用户展示。
package main

import "fmt"

// 用内存 logger 模拟，保证输出确定（生产可换 log/slog）。
type logger struct{ lines []string }

func (l *logger) Errorf(format string, args ...any) {
	l.lines = append(l.lines, fmt.Sprintf(format, args...))
}

// read 最底层：只返回错误，不记录。
func read() error { return fmt.Errorf("disk failure") }

// service 中间层：补充上下文后继续 return，不记录。
func service() error {
	if err := read(); err != nil {
		return fmt.Errorf("service: %w", err)
	}
	return nil
}

// handle 边界层：在这里记录恰好一次。
func handle(log *logger) error {
	if err := service(); err != nil {
		log.Errorf("request failed: %v", err)
		return err
	}
	return nil
}

func main() {
	log := &logger{}
	_ = handle(log)

	fmt.Println("log entries:", len(log.lines))
	for _, l := range log.lines {
		fmt.Println("  logged:", l)
	}

	// 对照反模式：若每层都记录，会出现多条重复噪音。
	antiLog := &logger{}
	if err := read(); err != nil {
		antiLog.Errorf("read: %v", err)
	}
	if err := read(); err != nil {
		antiLog.Errorf("service: %v", err)
	}
	fmt.Println("anti-pattern entries (duplicated):", len(antiLog.lines))
}

// T058 错误集合并发安全的收集。
//
// 并行处理多个子任务时，需要并发安全地收集错误。
// errors.Join（Go 1.20+）把多个错误合并成一个，errors.Is/As 仍可遍历全部。
package main

import (
	"errors"
	"fmt"
	"sort"
	"sync"
)

// task 模拟一个可能失败的任务。
func task(id int, failIDs map[int]bool) error {
	if failIDs[id] {
		return fmt.Errorf("task %d failed", id)
	}
	return nil
}

// runAll 并发跑所有任务，用 Mutex 保护错误切片，返回聚合错误。
func runAll(ids []int, failIDs map[int]bool) error {
	var mu sync.Mutex
	var errs []error

	var wg sync.WaitGroup
	for _, id := range ids {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			if err := task(id, failIDs); err != nil {
				mu.Lock()
				errs = append(errs, err)
				mu.Unlock()
			}
		}(id)
	}
	wg.Wait()

	return errors.Join(errs...)
}

// multiUnwrapper 是 errors.Join 返回值实现的接口：可展开出多个错误。
type multiUnwrapper interface{ Unwrap() []error }

func main() {
	ids := []int{1, 2, 3, 4, 5}
	failIDs := map[int]bool{2: true, 4: true}

	err := runAll(ids, failIDs)
	if err != nil {
		// Join 的结果可通过 Unwrap() []error 展开成多个子错误。
		if mu, ok := err.(multiUnwrapper); ok {
			parts := make([]string, 0, len(mu.Unwrap()))
			for _, e := range mu.Unwrap() {
				parts = append(parts, e.Error())
			}
			// 并发完成顺序不定，排序以保证输出确定。
			sort.Strings(parts)
			fmt.Println("collected errors:", len(parts))
			for _, p := range parts {
				fmt.Println(" ", p)
			}
		}
	}

	// 无失败时返回 nil。
	fmt.Println("all-ok err is nil:", runAll(ids, map[int]bool{}) == nil)

	// 演示单个 error 的 Unwrap 对 Join 结果不可用（它返回 nil）。
	fmt.Println("single Unwrap(join) is nil:", errors.Unwrap(err) == nil)
}

// T059 包、导出规则与初始化顺序。
//
// 包把代码分组；导出（大写）标识符可被其他包访问，小写仅包内可见。
// init 函数与包级变量初始化在包被导入时按依赖顺序自动执行。
//
// 完整多文件多包工程（module-project，不能一键导入）：
//   T059/
//   ├── go.mod              // module qfli.example/t059  (go 1.21)
//   ├── main.go             // 本文件：程序入口
//   ├── internal/config/config.go  // 包 config：包级变量 + init
//   └── internal/util/util.go      // 包 util：导出/非导出演示
//
// 运行（官方 SDK）：go run .
//
// 为在单文件内演示同一机制，这里用本包内的包级变量初始化与 init，
// 并注释说明真实的跨包结构。
package main

import "fmt"

// 包级变量按声明顺序初始化。
var a = 1
var b = a + 1 // 依赖 a

// exported 大写导出；unexported 小写仅本包可见。
const exported = "visible outside package"
const unexported = "visible only inside package"

// init 在 main 之前执行；多个 init 按文件/声明顺序执行。
func init() {
	fmt.Println("init: package config loaded, a =", a)
}

func main() {
	fmt.Println("a =", a, "b =", b)
	fmt.Println("exported:", exported)
	fmt.Println("unexported:", unexported)

	// 真实工程里，config 包的 init 会先于本 main 包执行（导入依赖顺序）。
	fmt.Println("init runs before main; across packages it follows import order")
}

// T060 Go Modules：go.mod 与依赖版本。
//
// go.mod 声明模块路径与 Go 版本，并记录依赖及版本；go.sum 记录校验和。
// 本例演示“本地替换（replace）”——在完全离线、无第三方依赖的前提下，
// 用 replace 指向同仓本地目录来演示模块依赖解析。
//
// 完整多模块工程（module-project，不能一键导入）：
//   T060/
//   ├── go.mod        // module qfli.example/t060; replace qfli.example/lib => ./lib
//   ├── main.go       // 本文件：导入 lib 包
//   └── lib/
//       ├── go.mod    // module qfli.example/lib  (go 1.21)
//       └── lib.go    // 提供 Greeting()
//
// 运行（官方 SDK，离线）：go run .
//
// 为在单文件内演示“模块版本/依赖”的解析结果，这里内联一个语义化版本比较，
// 并注明确切的 go.mod 结构与命令。
package main

import (
	"fmt"
	"strings"
)

// Version 是简化语义化版本。
type Version struct{ Major, Minor, Patch int }

func parse(s string) Version {
	s = strings.TrimPrefix(s, "v")
	var v Version
	fmt.Sscanf(s, "%d.%d.%d", &v.Major, &v.Minor, &v.Patch)
	return v
}

func compare(a, b Version) int {
	switch {
	case a.Major != b.Major:
		return a.Major - b.Major
	case a.Minor != b.Minor:
		return a.Minor - b.Minor
	default:
		return a.Patch - b.Patch
	}
}

func main() {
	// 模拟 replace + require 的解析：本地 replace 的模块版本仍按声明参与选择。
	require := []string{"v0.1.0", "v0.1.2", "v0.1.1"}
	best := parse(require[0])
	for _, r := range require[1:] {
		if v := parse(r); compare(v, best) > 0 {
			best = v
		}
	}
	fmt.Printf("selected local module version: v%d.%d.%d\n", best.Major, best.Minor, best.Patch)

	fmt.Println("go.mod:")
	fmt.Println("  module qfli.example/t060")
	fmt.Println("  go 1.21")
	fmt.Println("  require qfli.example/lib v0.1.2")
	fmt.Println("  replace qfli.example/lib => ./lib")
	fmt.Println("run: go run .  (no network; resolved via local replace)")
}

