// T062 泛型一：类型参数与约束。
//
// Min/Max 在没有泛型时要为每种类型各写一份（或在 interface{} 上做断言），
// 泛型用 [T cmp.Ordered] 表达"T 必须可比较大小"，一份代码服务多种类型。
// 注意：泛型属于 Go 1.18+ 的静态编译特性，本项目的移动端 Yaegi 解释器
// 未实测支持，因此本主题标记为 desktop only。
package main

import (
	"cmp"
	"fmt"
)

// Min 返回 a、b 中较小者。T 被约束为 cmp.Ordered，
// 因此可以在函数体内直接使用 < 比较。
func Min[T cmp.Ordered](a, b T) T {
	if a < b {
		return a
	}
	return b
}

// Max 同理返回较大者。编译器会为每个实际类型参数实例化一份机器码。
func Max[T cmp.Ordered](a, b T) T {
	if a > b {
		return a
	}
	return b
}

func main() {
	fmt.Println("Min[int](3, 7) =", Min(3, 7))
	fmt.Println("Max[int](3, 7) =", Max(3, 7))

	// 字符串也满足 cmp.Ordered（按字典序比较）。
	fmt.Println("Min[string](\"pear\", \"apple\") =", Min("pear", "apple"))

	// 浮点同样适用；没有为 float64 再写一份代码。
	fmt.Println("Max[float64](2.5, 1.5) =", Max(2.5, 1.5))
}

// T063 泛型二：自定义约束与联合类型。
//
// 约束不仅能用一个现成的接口（如 cmp.Ordered），还能自己定义：
//   type Number interface { ~int | ~float64 }
// 其中 ~int 表示"底层类型是 int 的任意命名类型"，| 是类型并集。
// Sum 因此可以同时接受整数和浮点，且仍然保有编译期类型检查。
// 泛型 = desktop only（移动端 Yaegi 未实测）。
package main

import "fmt"

// Number 是一个自定义约束：允许底层类型为 int、int64 或 float64 的任意类型。
type Number interface {
	~int | ~int64 | ~float64
}

// Sum 把切片里所有元素相加。因为 T 满足 Number，可以直接用 + 运算。
func Sum[T Number](values []T) T {
	var total T // 零值：数值类型为 0
	for _, v := range values {
		total += v
	}
	return total
}

// Celsius 是一个"底层类型为 float64"的命名类型，它同样满足 Number，
// 这就是 ~ 的作用：不要求类型本身叫 float64，只要底层是 float64。
type Celsius float64

func main() {
	fmt.Println("Sum([]int{1,2,3}) =", Sum([]int{1, 2, 3}))
	fmt.Println("Sum([]int64{10,20,30}) =", Sum([]int64{10, 20, 30}))
	fmt.Println("Sum([]float64{1.5,2.5}) =", Sum([]float64{1.5, 2.5}))

	temps := []Celsius{20.5, 19.5, 21.0}
	fmt.Println("Sum([]Celsius{...}) =", Sum(temps))
}

// T064 泛型三：泛型类型（容器）。
//
// 泛型不仅能用于函数，也能定义带类型参数的类型。Stack[T] 用切片存元素，
// 压栈/弹栈/判空都由同一份代码实现，实例化 Stack[int]、Stack[string] 都行。
// 泛型 = desktop only（移动端 Yaegi 未实测）。
package main

import "fmt"

// Stack 是一个后进先出（LIFO）栈。类型参数 T 是元素类型。
type Stack[T any] struct {
	items []T
}

// Push 把元素压入栈顶。
func (s *Stack[T]) Push(v T) {
	s.items = append(s.items, v)
}

// Pop 弹出栈顶元素。第二个返回值表示是否成功（空栈时 ok=false）。
func (s *Stack[T]) Pop() (T, bool) {
	var zero T
	if len(s.items) == 0 {
		return zero, false
	}
	last := len(s.items) - 1
	v := s.items[last]
	s.items = s.items[:last]
	return v, true
}

// Len 返回当前元素个数。
func (s *Stack[T]) Len() int { return len(s.items) }

func main() {
	var ints Stack[int]
	ints.Push(1)
	ints.Push(2)
	ints.Push(3)

	for ints.Len() > 0 {
		v, _ := ints.Pop()
		fmt.Println("popped int:", v)
	}
	_, ok := ints.Pop()
	fmt.Println("pop empty stack ok =", ok)

	var words Stack[string]
	words.Push("go")
	words.Push("generics")
	w, _ := words.Pop()
	fmt.Println("popped string:", w)
}

// T065 泛型与接口的选型对比。
//
// 同一道题——"对一组元素求和"——用两种方式实现：
//   1) 泛型函数 SumGeneric[T]：编译期特化，无装箱、无断言，但约束必须能表达运算。
//   2) 接口 summable：运行期多态，能容纳异构实现，但有类型断言/装箱开销。
// 运行结果相同；差别在"类型安全与性能"和"扩展性"之间的取舍。
// 泛型 = desktop only（移动端 Yaegi 未实测）。
package main

import "fmt"

// —— 方案一：泛型 ——
type Number interface{ ~int | ~float64 }

func SumGeneric[T Number](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

// —— 方案二：接口 ——
// Summable 是任何能自报数值的类型的接口。
type Summable interface {
	Value() float64
}

// SumInterface 通过接口方法求和，返回 float64。
func SumInterface(xs []Summable) float64 {
	var total float64
	for _, x := range xs {
		total += x.Value()
	}
	return total
}

// Money 是一个实现了 Summable 的具体类型。
type Money float64

func (m Money) Value() float64 { return float64(m) }

func main() {
	nums := []int{1, 2, 3, 4}
	fmt.Println("generic Sum[int] =", SumGeneric(nums))
	fmt.Println("generic Sum[float64] =", SumGeneric([]float64{1.5, 2.5}))

	sums := []Summable{Money(1.5), Money(2.5), Money(3.0)}
	fmt.Println("interface sum =", SumInterface(sums))
}

// T066 依赖注入：显式传递优于全局。
//
// 反例：handler 里直接调用 time.Now() 或某个全局单例，测试无法替换、结果不可控。
// 正例：把"时钟"抽象成接口，由构造函数注入。生产用 realClock，测试注入固定时钟，
// 于是同一份业务逻辑既能在真实环境运行，也能在测试中得到确定结果。
package main

import (
	"fmt"
	"time"
)

// Clock 抽象"现在几点"，是唯一的外部依赖。
type Clock interface {
	Now() time.Time
}

// realClock 是生产实现。
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// fixedClock 是测试/演示用的确定性实现。
type fixedClock struct{ t time.Time }

func (c fixedClock) Now() time.Time { return c.t }

// Greeter 通过构造函数接收 Clock，而不是自己去 new 或读全局变量。
type Greeter struct {
	clock Clock
}

// NewGreeter 是唯一组装依赖的地方。
func NewGreeter(c Clock) *Greeter { return &Greeter{clock: c} }

// Greeting 使用注入的时钟；逻辑本身不关心时间从哪来。
func (g *Greeter) Greeting(name string) string {
	hour := g.clock.Now().Hour()
	part := "上午好"
	switch {
	case hour < 6:
		part = "凌晨好"
	case hour < 12:
		part = "上午好"
	case hour < 18:
		part = "下午好"
	default:
		part = "晚上好"
	}
	return fmt.Sprintf("%s，%s", part, name)
}

func main() {
	// 演示：注入固定时钟，输出完全确定（不受运行时刻影响）。
	noon := time.Date(2026, 10, 12, 14, 0, 0, 0, time.UTC)
	g := NewGreeter(fixedClock{t: noon})
	fmt.Println(g.Greeting("gopher"))

	morning := NewGreeter(fixedClock{t: time.Date(2026, 10, 12, 8, 0, 0, 0, time.UTC)})
	fmt.Println(morning.Greeting("gopher"))

	// 生产环境换成 realClock 即可，Greeter 代码一行不改。
	_ = realClock{}
}

// T067 包级 API 设计与向后兼容：函数选项模式（Functional Options）。
//
// 直接暴露很多参数会让 API 一旦想加参数就破坏所有调用方。
// 选项模式把"可变配置"做成 func(*Server) 类型，NewServer 接收 0..N 个选项，
// 于是未来新增选项不会改变已有调用的签名——这就是向后兼容的关键。
package main

import (
	"fmt"
	"time"
)

// Server 是一个可配置的服务器描述（此处只做结构演示，不真正监听）。
type Server struct {
	Addr         string
	ReadTimeout  time.Duration
	MaxConns     int
	EnableAccess bool
}

// Option 是作用于 *Server 的配置函数。
type Option func(*Server)

// WithAddr 返回一个设置地址的选项。
func WithAddr(addr string) Option {
	return func(s *Server) { s.Addr = addr }
}

// WithReadTimeout 返回一个设置读超时的选项。
func WithReadTimeout(d time.Duration) Option {
	return func(s *Server) { s.ReadTimeout = d }
}

// WithMaxConns 返回一个设置最大连接数的选项。
func WithMaxConns(n int) Option {
	return func(s *Server) { s.MaxConns = n }
}

// WithAccessLog 打开访问日志。
func WithAccessLog() Option {
	return func(s *Server) { s.EnableAccess = true }
}

// NewServer 先建立一组安全默认值，再依次应用调用方传入的选项。
// 未来新增 WithXxx 也只是新增一个函数，不触碰此签名。
func NewServer(opts ...Option) *Server {
	s := &Server{
		Addr:        "127.0.0.1:8080",
		ReadTimeout: 5 * time.Second,
		MaxConns:    128,
	}
	for _, opt := range opts {
		opt(s)
	}
	return s
}

func main() {
	def := NewServer()
	fmt.Printf("default: addr=%s readTimeout=%s maxConns=%d access=%v\n",
		def.Addr, def.ReadTimeout, def.MaxConns, def.EnableAccess)

	custom := NewServer(
		WithAddr("0.0.0.0:9000"),
		WithReadTimeout(30*time.Second),
		WithMaxConns(1024),
		WithAccessLog(),
	)
	fmt.Printf("custom:  addr=%s readTimeout=%s maxConns=%d access=%v\n",
		custom.Addr, custom.ReadTimeout, custom.MaxConns, custom.EnableAccess)
}

// T068 语义化版本与最小版本选择（MVS）。
//
// 本示例演示"最小版本选择"的决策逻辑，不联网：给定若干依赖对版本的要求，
// 计算最终选中的版本——Go 的选择规则是"满足所有要求的最小可行版本"，
// 而不是"取最大"或"取最新"。这保证构建可复现。
//
// 完整工程结构（module-project，不能一键导入）：
//   demo/
//   ├── go.mod                // module demo\n\ngo 1.27
//   ├── main.go               // 本文件
//   ├── internal/version/     // 语义化版本解析
//   │   └── version.go
//   └── internal/mvs/mvs.go   // MVS 计算
// 运行：go run .
package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Version 是解析后的语义化版本 major.minor.patch。
type Version struct {
	Major, Minor, Patch int
}

// Parse 解析 "1.2.3" 形式的版本字符串。
func Parse(s string) (Version, error) {
	s = strings.TrimPrefix(s, "v")
	parts := strings.Split(s, ".")
	if len(parts) != 3 {
		return Version{}, fmt.Errorf("invalid version %q", s)
	}
	nums := make([]int, 3)
	for i, p := range parts {
		n, err := strconv.Atoi(p)
		if err != nil {
			return Version{}, fmt.Errorf("invalid version %q: %w", s, err)
		}
		nums[i] = n
	}
	return Version{nums[0], nums[1], nums[2]}, nil
}

// String 输出规范化的 v1.2.3 形式。
func (v Version) String() string { return fmt.Sprintf("v%d.%d.%d", v.Major, v.Minor, v.Patch) }

// Compare 按语义化版本规则比较：-1 小于，0 相等，1 大于。
func (v Version) Compare(o Version) int {
	switch {
	case v.Major != o.Major:
		return sign(v.Major - o.Major)
	case v.Minor != o.Minor:
		return sign(v.Minor - o.Minor)
	default:
		return sign(v.Patch - o.Patch)
	}
}

func sign(n int) int {
	if n < 0 {
		return -1
	}
	if n > 0 {
		return 1
	}
	return 0
}

// SelectMVS 返回满足所有约束的最小版本。
// constraints 是"每个依赖方要求的版本"列表。
func SelectMVS(constraints []Version) (Version, error) {
	if len(constraints) == 0 {
		return Version{}, fmt.Errorf("no constraints")
	}
	sorted := append([]Version(nil), constraints...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Compare(sorted[j]) < 0 })
	// 最小可行版本 = 所有下界中的最大者（因为每个版本都是它的下界）。
	best := sorted[0]
	for _, v := range sorted[1:] {
		if v.Compare(best) > 0 {
			best = v
		}
	}
	return best, nil
}

func main() {
	// 三个依赖方分别要求不同版本；MVS 选中满足全部要求的最小版本。
	raw := []string{"v1.2.0", "v1.5.3", "v1.4.9"}
	var cs []Version
	for _, r := range raw {
		v, err := Parse(r)
		if err != nil {
			panic(err)
		}
		cs = append(cs, v)
	}
	selected, err := SelectMVS(cs)
	if err != nil {
		panic(err)
	}
	fmt.Println("constraints:", strings.Join(raw, ", "))
	fmt.Println("selected (MVS) =", selected)

	// 对比：如果错误地"取最新/最大"，结果会不同，从而破坏最小依赖原则。
	maxV := cs[0]
	for _, v := range cs[1:] {
		if v.Compare(maxV) > 0 {
			maxV = v
		}
	}
	if maxV == selected {
		fmt.Println("此时最大版本恰好等于最小可行版本")
	}
}

