// T071 goroutine 基础与启动。
//
// 启动 goroutine 只需在调用前加 go。多个 goroutine 的完成顺序不确定，
// 因此本示例不打印"谁先谁后"，而是用 sync.WaitGroup 汇合后，
// 把各自写入的结果收集进切片，排序后再输出——保证输出确定。
package main

import (
	"fmt"
	"sort"
	"sync"
)

func main() {
	const n = 5
	results := make([]string, n)
	var wg sync.WaitGroup

	for i := 0; i < n; i++ {
		wg.Add(1)
		// i 作为参数传入，避免闭包共享同一个循环变量。
		go func(id int) {
			defer wg.Done()
			results[id] = fmt.Sprintf("worker-%d done", id)
		}(i)
	}

	// Wait 阻塞到所有 goroutine 调用 Done，保证 results 已全部写入。
	wg.Wait()

	// 排序消除 goroutine 完成顺序的不确定性，输出因此确定。
	sort.Strings(results)
	for _, r := range results {
		fmt.Println(r)
	}
}

// T072 channel 一：无缓冲与同步通信。
//
// 无缓冲 channel 的发送与接收会"互相等待"，因此天然是一次同步交接：
// 发送方阻塞直到有人接收，接收方阻塞直到有人发送。本示例用一个无缓冲
// channel 把值从 goroutine 交接给 main，顺序天然确定。
package main

import "fmt"

func main() {
	ch := make(chan string) // 无缓冲

	// 生产者 goroutine：发送后阻塞，直到 main 接收。
	go func() {
		ch <- "handoff payload"
	}()

	// 主 goroutine 接收，完成同步交接。
	got := <-ch
	fmt.Println("received:", got)

	// 再来一次，演示"先接收后发送"同样能配对。
	ch2 := make(chan int)
	go func() {
		ch2 <- 42
	}()
	fmt.Println("received:", <-ch2)
}

// T073 channel 二：有缓冲与容量语义。
//
// 有缓冲 channel 在缓冲未满时发送不阻塞，缓冲为空时接收才阻塞。
// 本示例用容量为 2 的通道：前两次发送立即成功，第三次会在缓冲满时阻塞，
// 于是我们用一个带 default 的 select 探测"是否还能发送"，把非确定性
// 的阻塞转成一个确定的布尔结果。
package main

import "fmt"

func main() {
	ch := make(chan int, 2) // 容量 2

	// 前两次发送不会阻塞。
	ch <- 10
	ch <- 20
	fmt.Println("buffered:", len(ch), "cap:", cap(ch))

	// 第三次发送：缓冲已满。用 select+default 非阻塞探测，得到确定结果。
	sent := false
	select {
	case ch <- 30:
		sent = true
	default:
		sent = false
	}
	fmt.Println("third send succeeded:", sent)

	// 取走一个后，容量腾出，再次探测就能成功。
	first := <-ch
	fmt.Println("first out:", first)

	again := false
	select {
	case ch <- 30:
		again = true
	default:
		again = false
	}
	fmt.Println("send after one receive succeeded:", again)

	// 清空：按 FIFO 顺序取出剩余元素，顺序确定。
	fmt.Println("remaining:", <-ch, <-ch)
}

// T074 channel 三：close 与 range 接收。
//
// close(ch) 表示"不会再有值发送进来"。对已关闭的 channel，range 会在
// 缓冲区取空后自然结束，接收的第二个返回值 ok 会变为 false。
// 发送方关闭、接收方用 range，是 producer/consumer 的惯用收尾方式。
package main

import "fmt"

func main() {
	ch := make(chan int)

	// 生产者：发送 1..5 后关闭 channel，通知消费者结束。
	go func() {
		for i := 1; i <= 5; i++ {
			ch <- i
		}
		close(ch)
	}()

	// 消费者：range 会一直读到 channel 关闭且缓冲为空。
	sum := 0
	count := 0
	for v := range ch {
		sum += v
		count++
	}
	fmt.Println("count:", count)
	fmt.Println("sum:", sum)

	// 逗号-ok 形式：关闭后再接收不阻塞，直接返回零值与 false。
	v, ok := <-ch
	fmt.Println("after close: value =", v, "ok =", ok)
}

// T075 select：多路复用与超时。
//
// select 同时等待多个 channel 操作，哪个先就绪就走哪个分支；
// 当所有分支都未就绪且写了 default，则立即走 default。
// 本示例用"已就绪的 channel"制造确定性的选择结果，
// 并用 time.After 演示超时分支，但断言只看"是否走到超时分支"，不看具体耗时。
package main

import (
	"fmt"
	"time"
)

func main() {
	ready := make(chan string, 1)
	ready <- "payload" // 预置，保证接收分支必然就绪

	// 只有一个分支就绪时，select 必然选择它，结果确定。
	select {
	case v := <-ready:
		fmt.Println("took ready channel:", v)
	default:
		fmt.Println("nothing ready")
	}

	// 演示超时分支：慢 channel 永远不发送，超时时间极短。
	// 我们断言"走了哪个分支"，不断言实际耗时。
	slow := make(chan int) // 无人发送
	select {
	case v := <-slow:
		fmt.Println("unexpected value:", v)
	case <-time.After(10 * time.Millisecond):
		fmt.Println("timeout branch taken")
	}

	// 两个 channel 都就绪时，Go 会随机选一个；因此这里不比较谁被选中，
	// 只断言"恰好取到一个值"，用集合语义消解随机性。
	a := make(chan int, 1)
	b := make(chan int, 1)
	a <- 1
	b <- 2
	select {
	case <-a:
		fmt.Println("selected exactly one ready channel")
	case <-b:
		fmt.Println("selected exactly one ready channel")
	}
}

// T076 单向 channel 与接口约束。
//
// 函数参数可以声明为只发 `chan<- T` 或只收 `<-chan T`，用类型系统表达
// "这个函数只应该发送/只应该接收"。它不能凭空创建方向，只能由双向 channel
// 隐式转换而来，因此起到文档与编译期约束的双重作用。
package main

import "fmt"

// producer 只能向 ch 发送，无法从中接收——编译器会阻止误用。
func producer(out chan<- int) {
	for i := 1; i <= 3; i++ {
		out <- i * i
	}
	close(out)
}

// consumer 只能从 ch 接收，无法发送。
func consumer(in <-chan int) int {
	sum := 0
	for v := range in {
		sum += v
	}
	return sum
}

func main() {
	// 双向 channel，分别以只发/只收的视角传给两个函数。
	ch := make(chan int, 3)
	producer(ch)
	fmt.Println("sum of squares 1..3 =", consumer(ch))

	// 只收 channel 也可直接用于 range；顺序由缓冲保证为 FIFO。
	nums := make(chan int, 3)
	nums <- 10
	nums <- 20
	nums <- 30
	close(nums)
	for v := range nums {
		fmt.Println("read:", v)
	}
}

// T077 sync.Mutex 与临界区保护。
//
// 多个 goroutine 并发对同一变量做 += 会产生数据竞争（race）：读-改-写三步
// 可能交错，导致丢失更新。Mutex 把这段临界区串行化，使结果确定。
//
// 这是一个 test-package 工程例子，不能一键导入。完整结构：
//   racecounter/
//   ├── go.mod          // module racecounter\n\ngo 1.27
//   └── counter_test.go // 本文件（含被测逻辑与测试）
// 运行（官方 SDK）：
//   go test ./...
//   go test -race ./...   // 官方 Go 独有，用于证明无数据竞争
//
// 移动端 Yaegi 不支持 go test/-race，故本主题 desktop only。
package racecounter

import (
	"sync"
	"testing"
)

// Counter 是被 Mutex 保护的计数器。
type Counter struct {
	mu sync.Mutex
	n  int
}

// Inc 在锁内完成读-改-写，避免竞争。
func (c *Counter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.n++
}

// Value 也在锁内读取，保证看到一致的值。
func (c *Counter) Value() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.n
}

// BadCounter 故意不加锁，用于对照（仅在文档中说明，不在测试里运行以免污染 -race）。
type BadCounter struct{ n int }

func (c *BadCounter) Inc() { c.n++ }

func TestCounterConcurrentIncrement(t *testing.T) {
	const goroutines = 100
	const perGoroutine = 100
	const want = goroutines * perGoroutine

	var c Counter
	var wg sync.WaitGroup
	wg.Add(goroutines)
	for i := 0; i < goroutines; i++ {
		go func() {
			defer wg.Done()
			for j := 0; j < perGoroutine; j++ {
				c.Inc()
			}
		}()
	}
	wg.Wait()

	// 确定性断言：最终计数必须精确等于期望值。
	if got := c.Value(); got != want {
		t.Fatalf("counter = %d, want %d", got, want)
	}
}

func TestCounterSequential(t *testing.T) {
	var c Counter
	for i := 0; i < 5; i++ {
		c.Inc()
	}
	if got := c.Value(); got != 5 {
		t.Fatalf("counter = %d, want 5", got)
	}
}

// T078 sync.RWMutex 读写分离。
//
// 读多写少的场景下，用 RWMutex 允许多个读并发进行，只有写才独占。
// 本示例维护一个配置映射：读操作可并发，写操作互斥，最终值确定。
//
// test-package 工程例子，不能一键导入。完整结构：
//   rwconfig/
//   ├── go.mod         // module rwconfig\n\ngo 1.27
//   └── config_test.go // 本文件
// 运行：go test ./...  /  go test -race ./...
// 移动端 Yaegi 不支持 go test/-race，desktop only。
package rwconfig

import (
	"strconv"
	"sync"
	"testing"
)

// Config 是并发安全的键值配置。
type Config struct {
	mu sync.RWMutex
	m  map[string]string
}

// NewConfig 建立空配置。
func NewConfig() *Config { return &Config{m: make(map[string]string)} }

// Set 写操作：独占锁。
func (c *Config) Set(k, v string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.m[k] = v
}

// Get 读操作：共享锁，多读可并发。
func (c *Config) Get(k string) (string, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	v, ok := c.m[k]
	return v, ok
}

func TestConfigConcurrentReadWrite(t *testing.T) {
	c := NewConfig()
	var wg sync.WaitGroup

	// 若干写者写入互不相同的键。
	const writers = 20
	wg.Add(writers)
	for i := 0; i < writers; i++ {
		go func(i int) {
			defer wg.Done()
			c.Set("k"+strconv.Itoa(i), strconv.Itoa(i))
		}(i)
	}
	wg.Wait()

	// 若干读者并发读取；确定性断言：每个键都能读回正确值。
	const readers = 50
	wg.Add(readers)
	errs := make(chan string, readers)
	for i := 0; i < readers; i++ {
		go func(i int) {
			defer wg.Done()
			key := "k" + strconv.Itoa(i%writers)
			v, ok := c.Get(key)
			if !ok || v != strconv.Itoa(i%writers) {
				errs <- "bad value for " + key
			}
		}(i)
	}
	wg.Wait()
	close(errs)

	for e := range errs {
		t.Fatal(e)
	}
}

// T079 sync.WaitGroup 与一次性任务 sync.Once。
//
// WaitGroup 用于等待一组 goroutine 完成；Once 保证某个初始化"在并发下也只
// 执行一次"。本示例用一次受 Once 保护的初始化 + 多 goroutine 并发调用，
// 断言初始化恰好发生一次，并用 WaitGroup 汇合。
package main

import (
	"fmt"
	"sync"
	"sync/atomic"
)

func main() {
	var once sync.Once
	var initCount int32 // 用原子计数，证明初始化只跑了一次

	initResource := func() {
		atomic.AddInt32(&initCount, 1)
	}

	// 多个 goroutine 同时请求初始化。
	const n = 8
	var wg sync.WaitGroup
	values := make([]int, n)
	wg.Add(n)
	for i := 0; i < n; i++ {
		go func(id int) {
			defer wg.Done()
			once.Do(initResource) // 只有第一个到达的 goroutine 会执行
			values[id] = id * id
		}(i)
	}
	wg.Wait()

	fmt.Println("init executed count:", atomic.LoadInt32(&initCount))
	fmt.Println("all goroutines finished:", len(values) == n)
	fmt.Println("sum of squares:", sum(values))
}

func sum(xs []int) int {
	t := 0
	for _, x := range xs {
		t += x
	}
	return t
}

// T080 sync.Pool 与临时对象复用。
//
// sync.Pool 缓存可复用对象，减少高频分配的压力。注意：Pool 中的对象可能被
// GC 随时回收，因此不能用于持久状态，只能当"临时缓冲池"。
//
// 这是一个 test-package / benchmark 工程例子，不能一键导入。完整结构：
//   poolbench/
//   ├── go.mod        // module poolbench\n\ngo 1.27
//   └── pool_test.go  // 本文件
// 运行（官方 SDK）：
//   go test ./...                      // 功能测试（确定性）
//   go test -bench . -benchmem ./...   // 只看分配指标，不作为通过条件
//
// 断言策略：功能测试用确定性"内容正确"断言；benchmark 只要求能跑出 ns/op。
// 移动端不支持 bench，desktop only。
package poolbench

import (
	"bytes"
	"sync"
	"testing"
)

var bufPool = sync.Pool{
	New: func() any { return new(bytes.Buffer) },
}

// render 用池中的 Buffer 组装字符串，用完重置并放回。
func render(parts []string) string {
	buf := bufPool.Get().(*bytes.Buffer)
	buf.Reset()
	defer bufPool.Put(buf)
	for _, p := range parts {
		buf.WriteString(p)
	}
	return buf.String()
}

// renderNoPool 不使用池，每次新建 Buffer，作为对照。
func renderNoPool(parts []string) string {
	var buf bytes.Buffer
	for _, p := range parts {
		buf.WriteString(p)
	}
	return buf.String()
}

func TestRenderCorrect(t *testing.T) {
	parts := []string{"go", "-", "pool"}
	if got, want := render(parts), "go-pool"; got != want {
		t.Fatalf("render = %q, want %q", got, want)
	}
	// 复用一个池对象多次，结果必须仍然正确（证明 Reset 有效）。
	if got := render([]string{"a", "b"}); got != "ab" {
		t.Fatalf("second render = %q, want %q", got, "ab")
	}
}

func TestRenderNoPoolMatches(t *testing.T) {
	parts := []string{"x", "y", "z"}
	if render(parts) != renderNoPool(parts) {
		t.Fatal("pooled and unpooled results differ")
	}
}

func BenchmarkRenderPool(b *testing.B) {
	parts := []string{"go", "-", "pool", "-", "bench"}
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		_ = render(parts)
	}
}

func BenchmarkRenderNoPool(b *testing.B) {
	parts := []string{"go", "-", "pool", "-", "bench"}
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		_ = renderNoPool(parts)
	}
}

// T081 原子操作 sync/atomic。
//
// 对于简单的计数/标志，atomic 提供无锁的原子读改写，避免锁开销。
// 本示例用 atomic.Int64 在多个 goroutine 中并发自增，最终值确定。
//
// test-package 工程例子，不能一键导入。完整结构：
//   atomiccount/
//   ├── go.mod          // module atomiccount\n\ngo 1.27
//   └── atomic_test.go  // 本文件
// 运行：go test ./...  /  go test -race ./...
// 移动端 Yaegi 对 sync/atomic 未实测，desktop only。
package atomiccount

import (
	"sync"
	"sync/atomic"
	"testing"
)

// Counter 用原子量计数。
type Counter struct{ n atomic.Int64 }

// Inc 原子自增。
func (c *Counter) Inc() { c.n.Add(1) }

// Value 原子读取。
func (c *Counter) Value() int64 { return c.n.Load() }

func TestAtomicConcurrentIncrement(t *testing.T) {
	const goroutines = 64
	const per = 1000
	const want = goroutines * per

	var c Counter
	var wg sync.WaitGroup
	wg.Add(goroutines)
	for i := 0; i < goroutines; i++ {
		go func() {
			defer wg.Done()
			for j := 0; j < per; j++ {
				c.Inc()
			}
		}()
	}
	wg.Wait()

	// 确定性断言：无锁自增也必须得到精确的总数。
	if got := c.Value(); got != want {
		t.Fatalf("value = %d, want %d", got, want)
	}
}

func TestAtomicCompareAndSwap(t *testing.T) {
	var n atomic.Int64
	n.Store(5)
	// 只有当当前值等于 5 时才替换为 9。
	swapped := n.CompareAndSwap(5, 9)
	if !swapped || n.Load() != 9 {
		t.Fatalf("CAS failed: swapped=%v value=%d", swapped, n.Load())
	}
	// 当前值已是 9，用 5 作为旧值会失败。
	if n.CompareAndSwap(5, 100) {
		t.Fatal("unexpected CAS success")
	}
}

// T082 context 一：取消与传播。
//
// context.WithCancel 派生一个可取消的上下文；调用 cancel() 会关闭 Done()
// 返回的 channel，所有监听它的下游任务据此提前退出。本示例启动一个循环
// 任务，取消后通过 channel 汇报"已退出"，主流程等待该信号，结果确定。
package main

import (
	"context"
	"fmt"
)

func main() {
	ctx, cancel := context.WithCancel(context.Background())

	done := make(chan struct{})
	go func() {
		// 任务循环：每次迭代检查是否被取消。
		for i := 0; ; i++ {
			select {
			case <-ctx.Done():
				// 被取消：报告原因并退出。
				fmt.Println("worker stopped:", ctx.Err())
				close(done)
				return
			default:
				// 正常继续（这里不做事，仅计数到某个点后自行取消）。
				if i == 3 {
					fmt.Println("worker reached checkpoint, requesting cancel")
					cancel()
				}
			}
		}
	}()

	// 等待 worker 确认退出。不依赖睡眠/时间，用 channel 做同步。
	<-done
	fmt.Println("main observed worker exit")

	// 传播：派生的子 context 也会随父取消而 Done。
	parent, pcancel := context.WithCancel(context.Background())
	child, ccancel := context.WithCancel(parent)
	pcancel()
	<-child.Done()
	fmt.Println("child canceled by parent:", child.Err())
	ccancel()
}

// T083 context 二：超时与截止时间。
//
// WithTimeout 在指定时长后自动取消，超时后 ctx.Err() 返回
// context.DeadlineExceeded。本示例只断言「超时是否发生」这类语义结果，
// 不让任何分支依赖墙钟或调度竞速：慢任务用永不就绪的 channel 等待超时，
// 快/未取消路径用一个不会被取消的 context 顺序验证。
package main

import (
	"context"
	"errors"
	"fmt"
)

func main() {
	// 场景一：任务永不完成 -> 一定超时。选择超时分支是确定性的。
	slowCtx, slowCancel := context.WithTimeout(context.Background(), 1)
	defer slowCancel()
	select {
	case <-neverReady():
		fmt.Println("slow: task finished")
	case <-slowCtx.Done():
		fmt.Println("slow: deadline exceeded =", errors.Is(slowCtx.Err(), context.DeadlineExceeded))
	}

	// 场景二：未取消的 context -> 顺序返回结果，不依赖时间竞速。
	okCtx, okCancel := context.WithCancel(context.Background())
	defer okCancel()
	result, err := doWork(okCtx)
	fmt.Println("ok: result =", result, "err =", err)

	// 场景三：显式取消后立即返回 context.Canceled。
	canceledCtx, cancel := context.WithCancel(context.Background())
	cancel()
	_, err = doWork(canceledCtx)
	fmt.Println("canceled: err is context canceled =", errors.Is(err, context.Canceled))
}

// doWork 在 ctx 已取消时返回错误，否则顺序返回结果。
func doWork(ctx context.Context) (int, error) {
	select {
	case <-ctx.Done():
		return 0, ctx.Err()
	default:
		return 42, nil
	}
}

// neverReady 返回一个永不就绪的 channel，用于确定性地触发超时分支。
func neverReady() <-chan struct{} { return make(chan struct{}) }

// T084 并发模式：worker pool 与 errgroup 式编排。
//
// 用固定数量的 worker 从任务 channel 取活、把结果写入结果 channel，
// 是经典的 worker pool。本示例不引入第三方 errgroup，而是用标准库
// WaitGroup + error channel 实现等价"并行执行并在有错时返回"的编排。
// 结果收集后排序输出，保证确定性。
package main

import (
	"errors"
	"fmt"
	"sort"
	"sync"
)

func main() {
	jobs := make([]int, 20)
	for i := range jobs {
		jobs[i] = i + 1
	}

	results, err := runPool(jobs, 4, func(n int) (int, error) {
		if n == 13 {
			return 0, errors.New("unlucky 13")
		}
		return n * n, nil
	})
	if err != nil {
		fmt.Println("pool error:", err)
	}

	// 排序后输出，消除 worker 完成顺序的不确定性。
	sort.Ints(results)
	fmt.Println("squares (sorted):", results)
}

// runPool 用 workers 个 goroutine 处理 jobs，返回排序无关的成功结果切片。
// 语义上等价于 errgroup：任一任务出错即记录；这里采用"收集首个错误"策略。
func runPool(jobs []int, workers int, fn func(int) (int, error)) ([]int, error) {
	in := make(chan int)
	out := make(chan int)
	errCh := make(chan error, 1)

	var wg sync.WaitGroup
	wg.Add(workers)
	for w := 0; w < workers; w++ {
		go func() {
			defer wg.Done()
			for n := range in {
				v, err := fn(n)
				if err != nil {
					select {
					case errCh <- err: // 只记录第一个错误
					default:
					}
					continue
				}
				out <- v
			}
		}()
	}

	// 喂任务。
	go func() {
		for _, n := range jobs {
			in <- n
		}
		close(in)
	}()

	// 收结果。
	var results []int
	collectDone := make(chan struct{})
	go func() {
		for v := range out {
			results = append(results, v)
		}
		close(collectDone)
	}()

	wg.Wait()
	close(out)
	<-collectDone

	select {
	case err := <-errCh:
		return results, err
	default:
		return results, nil
	}
}

// T085 io.Reader / io.Writer 抽象。
//
// io.Reader 只有一个 Read([]byte) 方法，io.Writer 只有一个 Write([]byte) 方法。
// 任何实现了它们的东西都能互相组合：文件、网络、内存缓冲、字符串……
// 本示例把字符串当 Reader、把 bytes.Buffer 当 Writer，用 io.Copy 搬运，
// 从而无需知道底层到底是什么。
package main

import (
	"bytes"
	"fmt"
	"io"
	"strings"
)

func main() {
	// strings.Reader 实现了 io.Reader。
	var r io.Reader = strings.NewReader("hello, io.Reader")

	// bytes.Buffer 实现了 io.Writer。
	var w io.Writer = &bytes.Buffer{}

	// io.Copy 只依赖这两个接口，不关心具体类型。
	n, err := io.Copy(w, r)
	fmt.Println("copied bytes:", n, "err:", err)
	fmt.Println("buffer content:", w.(*bytes.Buffer).String())

	// 自定义 Reader：把固定字节重复 n 次。
	rr := &repeatReader{data: []byte("ab"), times: 3}
	out, _ := io.ReadAll(rr)
	fmt.Println("custom reader:", string(out))
}

// repeatReader 是自定义 io.Reader，演示只要实现 Read 就能被 io 工具使用。
type repeatReader struct {
	data  []byte
	times int
	pos   int
}

func (r *repeatReader) Read(p []byte) (int, error) {
	// 计算还剩多少重复次数。
	if r.pos >= len(r.data)*r.times {
		return 0, io.EOF
	}
	n := copy(p, r.data[r.pos%len(r.data):])
	r.pos += n
	return n, nil
}

// T086 文件读写：os.Open/Create 与缓冲。
//
// 本示例在系统临时目录里创建文件，写入内容后读回，最后清理。
// 使用 os.CreateTemp 得到唯一路径，避免污染工作目录；
// 关键习惯：写后 Close 才能保证数据落盘，读前也用 defer Close。
package main

import (
	"fmt"
	"os"
	"path/filepath"
)

func main() {
	dir, err := os.MkdirTemp("", "qfli-t086-")
	if err != nil {
		panic(err)
	}
	// defer 保证函数退出时清理整个临时目录。
	defer os.RemoveAll(dir)

	path := filepath.Join(dir, "notes.txt")

	// 写入：os.Create 会截断或新建文件。
	f, err := os.Create(path)
	if err != nil {
		panic(err)
	}
	content := "line one\nline two\n"
	if _, err := f.WriteString(content); err != nil {
		f.Close()
		panic(err)
	}
	// Close 必须在再次打开前调用，否则缓冲/句柄状态不一致。
	if err := f.Close(); err != nil {
		panic(err)
	}

	// 读取：os.ReadFile 一次性读入。
	data, err := os.ReadFile(path)
	if err != nil {
		panic(err)
	}
	fmt.Println("read back:")
	fmt.Print(string(data))

	// 校验字节数，作为确定性断言。
	info, _ := os.Stat(path)
	fmt.Println("size matches:", int(info.Size()) == len(content))
}

// T087 bufio：按行/按词扫描与缓冲写。
//
// bufio.Scanner 把 Reader 包装成"按行/按词"的迭代器，内部用缓冲减少系统调用。
// 注意默认单行上限约 64KB，超长行需要 Buffer() 调大上限。
// 本示例按行与按词两种方式扫描同一段文本，统计结果确定。
package main

import (
	"bufio"
	"fmt"
	"strings"
)

func main() {
	const text = "go is fun\nbufio scans lines\nand words too\n"

	// 按行扫描。
	lineScan := bufio.NewScanner(strings.NewReader(text))
	lines := 0
	for lineScan.Scan() {
		lines++
		fmt.Printf("line %d: %s\n", lines, lineScan.Text())
	}
	fmt.Println("total lines:", lines)

	// 按词扫描：用 ScanWords 切分。
	wordScan := bufio.NewScanner(strings.NewReader(text))
	wordScan.Split(bufio.ScanWords)
	words := 0
	for wordScan.Scan() {
		words++
	}
	fmt.Println("total words:", words)
}

// T088 目录遍历与文件信息。
//
// os.ReadDir 返回目录条目并按文件名排序，因此输出天然确定。
// 用 FileInfo 可拿到名称、大小、是否为目录等元数据。
//
// 注意：目录条目的 Size() 是**文件系统相关**的值（Linux 上常见 4096，
// Windows 上常见 0），不能作为确定性输出。因此本示例对目录只打印类型，
// 只对普通文件打印大小——这样跨平台输出一致。
package main

import (
	"fmt"
	"os"
	"path/filepath"
)

func main() {
	dir, err := os.MkdirTemp("", "qfli-t088-")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)

	// 建两个文件和一个子目录，用于演示“是否目录”的判断。
	mustWrite(filepath.Join(dir, "alpha.txt"), "a")
	mustWrite(filepath.Join(dir, "beta.txt"), "bb")
	if err := os.Mkdir(filepath.Join(dir, "sub"), 0o755); err != nil {
		panic(err)
	}

	entries, err := os.ReadDir(dir)
	if err != nil {
		panic(err)
	}
	// ReadDir 已按名字排序：alpha.txt, beta.txt, sub。
	for _, e := range entries {
		if e.IsDir() {
			// 目录不打印易变的 size。
			fmt.Printf("%-10s dir\n", e.Name())
			continue
		}
		info, err := e.Info()
		if err != nil {
			panic(err)
		}
		fmt.Printf("%-10s file size=%d\n", e.Name(), info.Size())
	}
}

func mustWrite(path, content string) {
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		panic(err)
	}
}

// T089 JSON 一：Marshal/Unmarshal 基础。
//
// encoding/json 在 Go 值与 JSON 文本之间转换。Marshal 把结构体转成 JSON
// 字节；Unmarshal 把 JSON 解析回结构体。结构体字段必须是导出的（首字母大写）
// 才会被编码，否则会被忽略。
package main

import (
	"encoding/json"
	"fmt"
)

// Profile 是要被编解码的结构体。字段都导出。
type Profile struct {
	Name    string   `json:"name"`
	Age     int      `json:"age"`
	Hobbies []string `json:"hobbies"`
}

func main() {
	p := Profile{
		Name:    "gopher",
		Age:     15,
		Hobbies: []string{"coding", "reading"},
	}

	// 结构体 -> JSON。
	data, err := json.Marshal(p)
	if err != nil {
		panic(err)
	}
	fmt.Println("marshal:", string(data))

	// JSON -> 结构体。
	var back Profile
	if err := json.Unmarshal(data, &back); err != nil {
		panic(err)
	}
	fmt.Println("unmarshal name:", back.Name)
	fmt.Println("unmarshal age:", back.Age)
	fmt.Println("unmarshal hobbies:", back.Hobbies)

	// 往返一致：编码再解码应得到相等结构（切片需用元素比较）。
	again, _ := json.Marshal(back)
	fmt.Println("round-trip stable:", string(again) == string(data))
}

// T090 JSON 二：struct tag、omitempty 与自定义名称。
//
// struct tag 控制 JSON 字段名、是否省略空值、是否忽略字段等。
// omitempty 在字段为零值时省略该键；"-" 表示完全忽略；自定义名字改变键名。
// 本示例展示三种行为，输出确定。
package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

// Account 演示 tag 的常见用法。
type Account struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Password string `json:"-"`                    // 永不序列化
	Email    string `json:"email,omitempty"`      // 空则省略
	Nickname string `json:"nick_name,omitempty"`  // 改名 + 空则省略
	Balance  int    `json:"balance"`              // 零值也保留
}

func main() {
	a := Account{ID: 7, Name: "alice"}
	data, _ := json.Marshal(a)
	fmt.Println("minimal:", string(data))

	// 填入可选字段后，omitempty 的键出现。
	a.Email = "alice@example.com"
	a.Nickname = "ali"
	a.Balance = 100
	data2, _ := json.Marshal(a)
	fmt.Println("filled: ", string(data2))

	// Password 设为非空也永远不会出现在 JSON 中。
	a.Password = "secret"
	data3, _ := json.Marshal(a)
	fmt.Println("password hidden:", !strings.Contains(string(data3), "secret"))
}

