// T091 JSON 三：流式 Decoder/Encoder 与未知字段。
//
// json.Decoder 可以连续解码一个流中的多个 JSON 值（如 NDJSON），
// 比 Unmarshal 更适合逐步读取；Decoder.DisallowUnknownFields 会让
// 未知字段报错，便于严格校验。
// 本示例演示：连续解码多个对象、忽略未知字段（默认行为）。
package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

// Event 是流中的一个事件对象。
type Event struct {
	Type string `json:"type"`
	Code int    `json:"code"`
}

func main() {
	// 一个"流"里包含三个 JSON 对象，其中第二个还有未知字段 extra。
	stream := `{"type":"start","code":1}
{"type":"tick","code":2,"extra":"ignored"}
{"type":"stop","code":3}`

	dec := json.NewDecoder(strings.NewReader(stream))
	count := 0
	for dec.More() {
		var e Event
		// 默认忽略未知字段，因此第二行能成功解码。
		if err := dec.Decode(&e); err != nil {
			panic(err)
		}
		count++
		fmt.Printf("event %d: type=%s code=%d\n", count, e.Type, e.Code)
	}
	fmt.Println("decoded events:", count)

	// 严格模式：未知字段会报错。
	strict := json.NewDecoder(strings.NewReader(`{"type":"x","code":9,"bogus":true}`))
	strict.DisallowUnknownFields()
	var e Event
	err := strict.Decode(&e)
	fmt.Println("strict decode rejected unknown field:", err != nil)
}

// T092 时间一：time.Time、Duration 与格式化。
//
// Go 的时间格式化不使用格式串（如 yyyy-MM-dd），而是用一个"参考时间"
// 2006-01-02 15:04:05 作为布局。本示例使用固定时区与固定时间，
// 因此输出完全确定，不依赖当前时刻。
package main

import (
	"fmt"
	"time"
)

func main() {
	// 固定时区 UTC，构造一个确定的时间点。
	loc := time.UTC
	t := time.Date(2026, 10, 12, 14, 30, 45, 0, loc)

	// 参考布局 "2006-01-02 15:04:05"。
	fmt.Println("formatted:", t.Format("2006-01-02 15:04:05"))
	fmt.Println("date only:", t.Format("2006-01-02"))
	fmt.Println("RFC3339:  ", t.Format(time.RFC3339))

	// 解析：布局必须与实际字符串一致，否则报错。
	parsed, err := time.ParseInLocation("2006-01-02 15:04:05", "2020-01-02 03:04:05", loc)
	if err != nil {
		panic(err)
	}
	fmt.Println("parsed:", parsed.Format(time.RFC3339))

	// Duration 运算：纯时长加减，与墙钟无关。
	d := 90 * time.Minute
	fmt.Println("duration:", d)
	fmt.Println("duration minutes:", d.Minutes())

	later := t.Add(d)
	diff := later.Sub(t)
	fmt.Println("add 90m ->", later.Format("15:04:05"))
	fmt.Println("diff == 90m:", diff == d)
}

// T093 时间二：定时器、Ticker 与单调时钟。
//
// time.Timer 触发一次；time.Ticker 周期性触发。二者都基于单调时钟，
// 不受系统墙钟调整影响。本示例只断言"触发的次数"，不比较实际耗时，
// 因此输出确定、可离线验证。
package main

import (
	"fmt"
	"time"
)

func main() {
	// Timer：一次性。等待其通道被触发。
	timer := time.NewTimer(1 * time.Millisecond)
	<-timer.C
	fmt.Println("timer fired once")

	// Ticker：周期性。计数到 3 次后停止。
	ticker := time.NewTicker(1 * time.Millisecond)
	defer ticker.Stop()

	count := 0
	for range ticker.C {
		count++
		if count == 3 {
			break
		}
	}
	fmt.Println("ticker fired count:", count)

	// 停止后的 Ticker 不再触发（用 select+default 非阻塞探测，结果确定）。
	ticker.Stop()
	select {
	case <-ticker.C:
		fmt.Println("unexpected tick after stop")
	default:
		fmt.Println("no tick after stop")
	}

	// 演示 Now 的单调性：两次调用取差值为正（不断言具体数值）。
	start := time.Now()
	elapsed := time.Since(start)
	fmt.Println("elapsed is non-negative:", elapsed >= 0)
}

// T094 正则一：regexp 匹配与子匹配。
//
// regexp.MustCompile 在正则非法时 panic，适合包级常量；FindStringSubmatch
// 返回整体匹配与各捕获组。本示例从固定字符串中提取结构化字段，输出确定。
package main

import (
	"fmt"
	"regexp"
)

func main() {
	// 匹配形如 "key=value" 的日志片段，捕获 key 与 value。
	re := regexp.MustCompile(`(\w+)=(\w+)`)

	line := "user=alice role=admin active=true"
	// 找出所有匹配。
	all := re.FindAllStringSubmatch(line, -1)
	fmt.Println("matches:", len(all))
	for _, m := range all {
		// m[0] 是整体，m[1]/m[2] 是捕获组。
		fmt.Printf("  key=%-8s value=%s\n", m[1], m[2])
	}

	// 单个匹配。
	one := re.FindStringSubmatch("host=node1")
	fmt.Println("single full match:", one[0])
	fmt.Println("single group1:", one[1])
	fmt.Println("single group2:", one[2])

	// 无匹配时返回 nil；这里做存在性判断。
	fmt.Println("no match is nil:", re.FindStringSubmatch("nokv") == nil)
}

// T095 正则二：替换、分割与预编译复用。
//
// ReplaceAllStringFunc 允许用函数动态决定每个匹配的替换值；
// Split 用正则切分；预编译（MustCompile 到包级变量）避免重复编译。
// 本示例输出确定。
package main

import (
	"fmt"
	"regexp"
)

// 包级预编译：只编译一次，整个程序复用。
var (
	numberRe = regexp.MustCompile(`\d+`)
	spaceRe  = regexp.MustCompile(`\s+`)
)

func main() {
	src := "a1 b22 c333"

	// 条件替换：把每个数字 n 替换为 n*2 的字符串。
	doubled := numberRe.ReplaceAllStringFunc(src, func(m string) string {
		// m 一定是数字串，这里手工解析以避免引入 strconv 干扰阅读。
		n := 0
		for _, r := range m {
			n = n*10 + int(r-'0')
		}
		return fmt.Sprint(n * 2)
	})
	fmt.Println("doubled:", doubled)

	// 简单替换：把所有数字替换为 "#"。
	masked := numberRe.ReplaceAllString(src, "#")
	fmt.Println("masked: ", masked)

	// 用连续空白分割。
	parts := spaceRe.Split("one   two\tthree  four", -1)
	fmt.Println("split count:", len(parts))
	for i, p := range parts {
		fmt.Printf("  [%d]=%s\n", i, p)
	}
}

// T096 文本模板 text/template。
//
// text/template 用 {{.Field}} 占位符渲染结构化数据。模板可包含
// 条件 {{if}}、循环 {{range}}。本示例把渲染结果写入 bytes.Buffer，
// 再统一打印——不直接依赖 os.Stdout 捕获，输出因此确定、易测试。
package main

import (
	"bytes"
	"fmt"
	"text/template"
)

func main() {
	const tpl = `Inventory for {{.Owner}}:
{{range .Items}}- {{.Name}} x{{.Qty}} ({{if .InStock}}in stock{{else}}out of stock{{end}})
{{end}}Total lines: {{len .Items}}`

	data := struct {
		Owner string
		Items []struct {
			Name    string
			Qty     int
			InStock bool
		}
	}{
		Owner: "warehouse-a",
		Items: []struct {
			Name    string
			Qty     int
			InStock bool
		}{
			{"bolt", 100, true},
			{"nut", 0, false},
		},
	}

	t := template.Must(template.New("inv").Parse(tpl))

	// 渲染到内存缓冲，再打印，避免依赖底层 stdout 的捕获方式。
	var buf bytes.Buffer
	if err := t.Execute(&buf, data); err != nil {
		panic(err)
	}
	fmt.Println(buf.String())
