		mux.ServeHTTP(rec, req)
		if rec.Code != http.StatusOK {
			t.Fatalf("%s status = %d", c.path, rec.Code)
		}
		if got := rec.Body.String(); got != c.want {
			t.Fatalf("%s body = %q, want %q", c.path, got, c.want)
