// T101 请求与响应：Method、Header、状态码。
//
// Handler 可读取 r.Method / r.Header 并据此分支；用 w.WriteHeader 设置
// 状态码。方法不匹配时返回 405 Method Not Allowed 是常见约定。
//
// test-package 工程例子，不能一键导入。完整结构：
//   httpmethod/
//   ├── go.mod         // module httpmethod\n\ngo 1.27
//   └── method_test.go // 本文件
// 运行：go test ./...   desktop only。
package httpmethod

import (
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

// handler 只接受 POST；其他方法返回 405 并带 Allow 头。
func handler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", http.MethodPost)
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}
	// 回显自定义头。
	w.Header().Set("X-Echo", r.Header.Get("X-Token"))
	w.WriteHeader(http.StatusCreated)
	_, _ = io.WriteString(w, "created")
}

func TestMethodRouting(t *testing.T) {
	// POST：应 201。
	post := httptest.NewRequest(http.MethodPost, "/", nil)
	post.Header.Set("X-Token", "abc")
	postRec := httptest.NewRecorder()
	handler(postRec, post)
	if postRec.Code != http.StatusCreated {
		t.Fatalf("POST status = %d, want 201", postRec.Code)
	}
	if got := postRec.Header().Get("X-Echo"); got != "abc" {
		t.Fatalf("X-Echo = %q, want abc", got)
	}

	// GET：应 405 且带 Allow 头。
	get := httptest.NewRequest(http.MethodGet, "/", nil)
	getRec := httptest.NewRecorder()
	handler(getRec, get)
	if getRec.Code != http.StatusMethodNotAllowed {
		t.Fatalf("GET status = %d, want 405", getRec.Code)
	}
	if got := getRec.Header().Get("Allow"); got != http.MethodPost {
		t.Fatalf("Allow = %q, want POST", got)
	}
}

// T102 JSON API 与错误响应约定。
//
// 一个 JSON API 应统一响应结构：成功返回数据，失败返回错误码与消息，
// 并设置 Content-Type: application/json。本示例用统一 envelope 输出，
// 并测试正常与错误两条路径。
//
// test-package 工程例子，不能一键导入。完整结构：
//   httpjson/
//   ├── go.mod      // module httpjson\n\ngo 1.27
//   └── api_test.go // 本文件
// 运行：go test ./...   desktop only。
package httpjson

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

// Envelope 是所有响应的统一外壳。
type Envelope struct {
	OK    bool   `json:"ok"`
	Data  any    `json:"data,omitempty"`
	Error string `json:"error,omitempty"`
}

// handler 依赖查询参数 name：有则成功，无则错误。
func handler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	name := r.URL.Query().Get("name")
	if name == "" {
		w.WriteHeader(http.StatusBadRequest)
		_ = json.NewEncoder(w).Encode(Envelope{OK: false, Error: "name is required"})
		return
	}
	_ = json.NewEncoder(w).Encode(Envelope{OK: true, Data: map[string]string{"name": name}})
}

func TestJSONAPI(t *testing.T) {
	// 成功路径。
	okReq := httptest.NewRequest(http.MethodGet, "/?name=alice", nil)
	okRec := httptest.NewRecorder()
	handler(okRec, okReq)
	if okRec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200", okRec.Code)
	}
	if ct := okRec.Header().Get("Content-Type"); ct != "application/json" {
		t.Fatalf("content-type = %q", ct)
	}
	var okEnv Envelope
	if err := json.Unmarshal(okRec.Body.Bytes(), &okEnv); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if !okEnv.OK {
		t.Fatalf("ok = false, want true")
	}

	// 错误路径。
	badReq := httptest.NewRequest(http.MethodGet, "/", nil)
	badRec := httptest.NewRecorder()
	handler(badRec, badReq)
	if badRec.Code != http.StatusBadRequest {
		t.Fatalf("status = %d, want 400", badRec.Code)
	}
	var badEnv Envelope
	if err := json.Unmarshal(badRec.Body.Bytes(), &badEnv); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if badEnv.OK || badEnv.Error == "" {
		t.Fatalf("error envelope = %+v", badEnv)
	}
	var raw map[string]json.RawMessage
	_ = json.Unmarshal(badRec.Body.Bytes(), &raw)
	if _, present := raw["data"]; present {
		t.Fatal("error response must not include data")
	}
}

// T103 中间件：日志、恢复与链式组合。
//
// 中间件是"接收一个 Handler、返回一个 Handler"的函数，可在调用前后插入
// 逻辑（日志、恢复、鉴权）。多个中间件可链式包裹。本示例用中间件记录
// 请求方法并统计调用次数，用 httptest 断言链路确实被经过。
//
// test-package 工程例子，不能一键导入。完整结构：
//   httpmw/
//   ├── go.mod     // module httpmw\n\ngo 1.27
//   └── mw_test.go // 本文件
// 运行：go test ./...   desktop only。
package httpmw

import (
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

// Middleware 是标准中间件签名。
type Middleware func(http.Handler) http.Handler

// logging 记录每个经过的请求方法。
func logging(log *[]string) Middleware {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			*log = append(*log, r.Method+" "+r.URL.Path)
			next.ServeHTTP(w, r)
		})
	}
}

// recoverer 捕获 panic，返回 500，保证链路不崩。
func recoverer(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if rec := recover(); rec != nil {
				w.WriteHeader(http.StatusInternalServerError)
			}
		}()
		next.ServeHTTP(w, r)
	})
}

// chain 按顺序包裹：chain(h, a, b) == a(b(h))。
func chain(h http.Handler, mws ...Middleware) http.Handler {
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
	return h
}

func TestMiddlewareChain(t *testing.T) {
	var log []string

	final := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/boom" {
			panic("boom")
		}
		_, _ = io.WriteString(w, "ok")
	})
	h := chain(final, logging(&log), recoverer)

	// 正常请求。
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/ok", nil))
	if rec.Body.String() != "ok" {
		t.Fatalf("body = %q, want ok", rec.Body.String())
	}

	// panic 请求：recoverer 应返回 500。
	rec2 := httptest.NewRecorder()
	h.ServeHTTP(rec2, httptest.NewRequest(http.MethodGet, "/boom", nil))
	if rec2.Code != http.StatusInternalServerError {
		t.Fatalf("panic status = %d, want 500", rec2.Code)
	}

	// 日志中间件应记录两次，且顺序确定。
	if len(log) != 2 || log[0] != "GET /ok" || log[1] != "GET /boom" {
		t.Fatalf("log = %v", log)
	}
}

